processor-info.script:


String cmd = input.getText("cmd");	

if("excuteStatView".equals(cmd))
{
	executeSQL("excuteStatViewDel", connection, input, output);
	executeSQL(cmd, connection, input, output);
}else if("excuteStatMenu".equals(cmd))
{
	executeSQL("excuteStatMenuDel", connection, input, output);
	executeSQL(cmd, connection, input, output);
}else if("excuteStatPotal".equals(cmd))
{
	executeSQL("excuteStatPotalDel", connection, input, output);
	executeSQL(cmd, connection, input, output);
}else{	
	executeSQL(cmd, connection, input, output);
}
